#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime, timezone
import hashlib,json
ROOT=Path('/home/ubuntu/CHAOS'); LEDGER=ROOT/'research_ledger/RESEARCH_LEDGER_V1.jsonl'
def h(p): return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def rec(i,t,s,c,refs,n):
 r={'contract_ref':c,'created_at_utc':datetime.now(timezone.utc).isoformat(),'input_hashes':{p:h(p) for p in refs if (ROOT/p).exists()},'ledger_id':i,'notes':n,'output_refs':refs,'record_type':t,'status':s}; r['record_hash']=hashlib.sha256(json.dumps(r,sort_keys=True,ensure_ascii=False).encode()).hexdigest(); return r
rows=[rec('OECD_PMR_WITHIN_DOMAIN_TRANSITION_TEST_V1','transition_evidence','not_testable','experimental_contracts/OECD_PMR_WITHIN_DOMAIN_TRANSITION_CONTRACT_V1.json',['experiments/multi_domain_native_edges_v1/pmr_within_domain_v1/PMR_WITHIN_DOMAIN_TRANSITION_METRICS_V1.csv','experiments/multi_domain_native_edges_v1/pmr_within_domain_v1/PMR_WITHIN_DOMAIN_NULL_SUMMARY_V1.json','experiments/multi_domain_native_edges_v1/pmr_within_domain_v1/PMR_WITHIN_DOMAIN_TRANSITION_EVIDENCE_V1.jsonl'],'801 complete series; independent within-series permutation p=0.0001; no OOS or entity holdout; descriptive only'),rec('OECD_PMR_WITHIN_DOMAIN_STABILITY_V1','descriptive_stability','not_testable','experimental_contracts/OECD_PMR_WITHIN_DOMAIN_TRANSITION_CONTRACT_V1.json',['experiments/multi_domain_native_edges_v1/pmr_within_domain_v1/PMR_STABILITY_SUMMARY_V1.json','experiments/multi_domain_native_edges_v1/pmr_within_domain_v1/PMR_WITHIN_DOMAIN_TEST_REPORT_AR.md'],'directional concentration remained broad across 23/28 indicators and 25/29 economies across all three intervals; no predictive promotion'),rec('OECD_PMR_DEPENDENCY_AWARE_NULL_V1_1','transition_evidence','rejected','experimental_contracts/OECD_PMR_WITHIN_DOMAIN_STABILITY_NULL_CONTRACT_V1_1.json',['experiments/multi_domain_native_edges_v1/pmr_within_domain_v1/PMR_STABILITY_NULL_SENSITIVITY_V1_1.json','experiments/multi_domain_native_edges_v1/pmr_within_domain_v1/PMR_WITHIN_DOMAIN_TRANSITION_EVIDENCE_V1_1.jsonl'],'common-wave exact permutation p=1.0; cluster bootstrap q025=0.8135 to q975=0.8838 contains observed max; dependency-aware null not exceeded'),rec('OECD_PMR_TEST_GOVERNANCE_REFRESH_V1','supervisor_gate','pass','experimental_contracts/TRANSITION_EVIDENCE_SCHEMA_V1.json',['campaigns/CAMPAIGN_SHARED_GATE_V1/TRANSITION_EVIDENCE_SCHEMA_VALIDATION_V1.json','campaigns/CAMPAIGN_SHARED_GATE_V1/SUPERVISOR_GATE_DECISION_V1.json','experiments/macro_plus_eia_energy/evidence_graph_v1/EVIDENCE_GRAPH_SUMMARY.json','campaigns/CAMPAIGN_SHARED_GATE_V1/FINAL_SUPERVISOR_ELIGIBILITY_GATE_V1.json'],'PMR test passed schema/gate; 50 graph nodes and 52 edges; 2 admitted supported_predictive; 24 quarantined; 0 runtime-eligible; 0 causal claims')]
old=LEDGER.read_text(encoding='utf8').splitlines(); ids={json.loads(x)['ledger_id'] for x in old if x.strip()}; new=[r for r in rows if r['ledger_id'] not in ids]
with LEDGER.open('a',encoding='utf8') as f:
 for r in new:f.write(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n')
print(json.dumps({'appended':[r['ledger_id'] for r in new],'total_records':len(old)+len(new)},ensure_ascii=False,indent=2))
